#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
public:
    Cat(string n) : name(n) {
        cout << "先搭妈妈那一半：" << name << endl;
    }
    ~Cat() {
        cout << "后拆妈妈那一半：" << name << endl;
    }
};

class Kitten : public Cat {
public:
    Kitten(string n) : Cat(n) {
        cout << "再搭小猫那一半：" << name << endl;
    }
    ~Kitten() {
        cout << "先拆小猫那一半：" << name << endl;
    }
};

